            return @"ir.at"(@"ir.node", .@"text", 3, "ir.Text.routine");
        }
    };
    pub const Pat = struct {
        pub fn @"count"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"pat", 1, "ir.Pat.count");
        }
        pub fn @"codes"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"pat", 2, "ir.Pat.codes");
        }
        pub fn @"text"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"pat", 3, "ir.Pat.text");
        }
        pub fn @"capture"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"pat", 4, "ir.Pat.capture");
        }
        pub fn @"alts"(@"ir.node": @"ir.Sexp") []const @"ir.Sexp" {
            return @"ir.restAt"(@"ir.node", .@"pat", 5, "ir.Pat.alts");
        }
    };
    pub const Count = struct {
        pub fn @"min"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"count", 1, "ir.Count.min");
        }
        pub fn @"max"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"count", 2, "ir.Count.max");
        }
    };
};

/// Slot `slot` of `node`, a node of `kind` (checked in safety builds).
fn @"ir.at"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot] else .nil;
}

/// The children of `node` from `slot` on.
fn @"ir.restAt"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) []const Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot..] else &.{};
}

fn @"ir.check"(node: Sexp, comptime kind: Tag, comptime what: []const u8) void {
    if (@import("builtin").optimize.runtimeSafety() and !node.isKind(kind)) {
        const actual = if (node.kind()) |k| @tagName(k) else @tagName(node);
        std.debug.panic(what ++ ": node is '{s}', not '" ++ @tagName(kind) ++ "'", .{actual});
    }
}


// =============================================================================
// Grammar
// =============================================================================

/// Node spans and rule ids are recorded (`@schema` or `--spans`).
pub const nodeStore = true;
/// Element extents are kept for side-band labels and nested nodes.
const elemEnds = true;
/// Lists keep trailing nils: positions are fixed by the schema.
const keepTrailingNils = true;
const hasTrivia = false;
const hasRepair = false;
/// `@as` groups the promotable token may become (see `promote`).
const asGroups = 5;
const numSymbols = 275;
const endSymbol: u16 = 1;
const errorSymbol: u16 = 2;

fn tokenToSymbol(token: Token) u16 {
    return switch (token.cat) {
        .@"eof" => 1,
        .@"ident" => needsPromotion,
        .@"integer" => 123,
        .@"zdigits" => 124,
        .@"newline" => 125,
        .@"comment" => 126,
        .@"indent" => 132,
        .@"sp" => 135,
        .@"spaces" => 136,
        .@"string" => 190,
        .@"patend" => 196,
        .@"quesat" => 198,
        .@"real" => 257,
        .@"notques" => 219,
        .@"noteq" => 220,
        .@"notlt" => 223,
        .@"notgt" => 224,
        .@"notlbracket" => 228,
        .@"notrbracket" => 230,
        .@"followseq" => 231,
        .@"sortsafter" => 232,
        .@"sortsaftereq" => 233,
        .@"notsortsafter" => 234,
        .@"eqeq" => 249,
        .@"notampersand" => 251,
        .@"notexclaim" => 252,
        .@"lparen" => 127,
        .@"comma" => 128,
        .@"rparen" => 131,
        .@"dot" => 134,
        .@"colon" => 137,
        .@"at" => 140,
        .@"eq" => 141,
        .@"dollar" => 143,
        .@"plus" => 165,
        .@"caret" => 166,
        .@"pipe" => 175,
        .@"slash" => 187,
        .@"star" => 188,
        .@"hash" => 189,
        .@"exclaim" => 194,
        .@"question" => 195,
        .@"minus" => 205,
        .@"lt" => 221,
        .@"gt" => 222,
        .@"lbracket" => 227,
        .@"rbracket" => 229,
        .@"not" => 245,
        .@"underscore" => 246,
        .@"backslash" => 247,
        .@"ampersand" => 250,
        .@"lteq" => 225,
        .@"gteq" => 226,
        .@"starstar" => 248,
        else => 2, // error
    };
}

fn promote(self: *BaseParser, token: Token) u16 {
    // The ordinal of a match made in an earlier state (before a
    // reduction) is not this match's.
    self.lastMatchedId = 0;
    const text = self.source[token.pos..][0..token.len];
    if (text.len == 0) return promotableSymbol;
    if (self.tryPromote(0, text, lang.fnAs, &fnToSymbol, fnFallbackSymbol, false)) |sym| return sym;
    if (self.tryPromote(1, text, lang.svAs, &svToSymbol, svFallbackSymbol, false)) |sym| return sym;
    if (self.tryPromote(2, text, lang.isvAs, &isvToSymbol, isvFallbackSymbol, false)) |sym| return sym;
    if (self.tryPromote(3, text, lang.ssvnAs, &ssvnToSymbol, ssvnFallbackSymbol, false)) |sym| return sym;
    if (getAction(self.stateStack.last().?, promotableSymbol) != 0) return promotableSymbol;
    if (self.tryPromote(4, text, lang.cmdAs, &cmdToSymbol, cmdFallbackSymbol, true)) |sym| return sym;
    return promotableSymbol;
}

