fn restRoleOf(kind: Tag) ?struct { role: Role, slot: usize } {
    return switch (kind) {
        .@"routine" => .{ .role = .@"lines", .slot = 1 },
        .@"label" => .{ .role = .@"cmds", .slot = 4 },
        .@"line" => .{ .role = .@"cmds", .slot = 2 },
        .@"commands" => .{ .role = .@"cmds", .slot = 1 },
        .@"set" => .{ .role = .@"args", .slot = 2 },
        .@"new" => .{ .role = .@"args", .slot = 2 },
        .@"kill" => .{ .role = .@"args", .slot = 2 },
        .@"merge" => .{ .role = .@"args", .slot = 2 },
        .@"do" => .{ .role = .@"args", .slot = 2 },
        .@"goto" => .{ .role = .@"args", .slot = 2 },
        .@"break" => .{ .role = .@"args", .slot = 2 },
        .@"hang" => .{ .role = .@"args", .slot = 2 },
        .@"job" => .{ .role = .@"args", .slot = 2 },
        .@"xecute" => .{ .role = .@"args", .slot = 2 },
        .@"view" => .{ .role = .@"args", .slot = 2 },
        .@"open" => .{ .role = .@"args", .slot = 2 },
        .@"use" => .{ .role = .@"args", .slot = 2 },
